export function project(lon,lat){return {x:(lon+73.991)*111320*Math.cos(40.717*Math.PI/180)*.1,z:(40.717-lat)*111320*.1};}
export function unproject(x,z){return {lon:x/(111320*Math.cos(40.717*Math.PI/180)*.1)-73.991,lat:40.717-z/11132};}
export function makeStreetGraph(roads){const graph=new Map();for(const r of roads){if(!r.walk)continue;for(let i=0;i<r.nodes.length;i++){let id=r.nodes[i];if(!graph.has(id))graph.set(id,{id,x:r.points[i][0],z:r.points[i][1],y:r.bridge?.52:0,edges:new Map()});if(i){let prev=graph.get(r.nodes[i-1]),cur=graph.get(id);const d=Math.hypot(cur.x-prev.x,cur.z-prev.z);if(d){prev.edges.set(id,d);cur.edges.set(prev.id,d);}}}}// Keep the largest connected pedestrian network, excluding isolated courtyards.
let biggest=[],seen=new Set();for(const id of graph.keys()){if(seen.has(id))continue;let group=[],stack=[id];seen.add(id);while(stack.length){const next=stack.pop();group.push(next);for(const key of graph.get(next).edges.keys())if(!seen.has(key)){seen.add(key);stack.push(key)}}if(group.length>biggest.length)biggest=group;}const kept=new Set(biggest);return new Map([...graph].filter(([id])=>kept.has(id)));}
export function nearestNode(graph,p){let best=null,dist=Infinity;for(const node of graph.values()){let d=(node.x-p.x)**2+(node.z-p.z)**2;if(d<dist){dist=d;best=node}}return best;}
function nodeRoute(graph,start,end){let a=nearestNode(graph,start),b=nearestNode(graph,end);if(!a||!b)return [];let open=new Set([a.id]),distance=new Map([[a.id,0]]),from=new Map(),closed=new Set();while(open.size){let id=null,score=Infinity;for(const candidate of open){const p=graph.get(candidate),v=distance.get(candidate)+Math.hypot(p.x-b.x,p.z-b.z);if(v<score){score=v;id=candidate}}if(id===b.id){let ids=[id];while(from.has(id)){id=from.get(id);ids.push(id)}return ids.reverse().map(i=>({x:graph.get(i).x,z:graph.get(i).z,y:graph.get(i).y??0}));}open.delete(id);closed.add(id);for(const [next,cost] of graph.get(id).edges){if(closed.has(next))continue;const d=distance.get(id)+cost;if(d<(distance.get(next)??Infinity)){distance.set(next,d);from.set(next,id);open.add(next)}}}return [];}
export function advanceStep(position,target,maximum){const distance=Math.hypot(target.x-position.x,target.z-position.z);if(distance<.001)return {x:target.x,z:target.z,y:target.y??0,moved:0,arrived:true};const moved=Math.min(maximum,distance),ratio=moved/distance;return {x:position.x+(target.x-position.x)*ratio,z:position.z+(target.z-position.z)*ratio,y:(position.y??0)+((target.y??0)-(position.y??0))*ratio,moved,arrived:moved>=distance};}

// A redirected walk starts along its current road segment, never a diagonal to a nearby intersection.
export function cityRoute(graph,start,end){let edge=null,best=Infinity;for(const a of graph.values())for(const id of a.edges.keys()){const b=graph.get(id),dx=b.x-a.x,dz=b.z-a.z,len=dx*dx+dz*dz;if(!len)continue;const t=Math.max(0,Math.min(1,((start.x-a.x)*dx+(start.z-a.z)*dz)/len)),p={x:a.x+t*dx,z:a.z+t*dz,y:(a.y??0)+((b.y??0)-(a.y??0))*t},d=Math.hypot(p.x-start.x,p.z-start.z);if(d<best){best=d;edge={a,b,p};}}if(!edge)return nodeRoute(graph,start,end);let chosen=[],cost=Infinity;for(const endpoint of [edge.a,edge.b]){const route=nodeRoute(graph,endpoint,end);if(!route.length)continue;let total=0,prev=edge.p;for(const p of route){total+=Math.hypot(p.x-prev.x,p.z-prev.z);prev=p;}if(total<cost){cost=total;chosen=[edge.p,...route];}}return chosen;}
